/*
 * A274455  Sequence (or tree) generated by these rules: 1 is in S, and if x
 *          is in S, then x -1 and 2*x are in S, and duplicates are deleted as
 *          they occur.
 * https://oeis.org/A274455
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  sign, easy
 * Formula:   a(n) computed by BFS on a tree with rules x-1 and 2x, starting
 *            from 1 and removing duplicate nodes
 * Range:     i8 n <= 54, i16 n <= 2583, i32 n <= 9614, i64 n <= 9614,
 *            i128 n <= 9614, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

static seq_t *seq_cache = NULL;   /* array of all generated terms (and visited set)   */
static size_t seq_len   = 0;       /* number of terms stored so far                  */
static size_t seq_cap   = 0;       /* allocated capacity of seq_cache                */

static seq_t *queue = NULL;       /* queue of nodes yet to be expanded              */
static size_t q_front = 0;        /* first unprocessed element in queue             */
static size_t q_back  = 0;        /* index one past last element in queue           */
static size_t q_cap   = 0;        /* allocated capacity of the queue                */

/* Ensure seq_cache can hold at least new_cap elements.           */
static void ensure_seq_cache_capacity(size_t new_cap)
{
    if (seq_cap >= new_cap) return;
    size_t cap = seq_cap ? seq_cap : 64;
    while (cap < new_cap) cap <<= 1;
    seq_cache = (seq_t *)realloc(seq_cache, cap * sizeof(seq_t));
    seq_cap = cap;
}

/* Ensure queue can hold at least new_cap elements, preserving
   unprocessed elements.                                            */
static void ensure_queue_capacity(size_t new_cap)
{
    if (q_cap >= new_cap) return;
    size_t cap = q_cap ? q_cap : 64;
    while (cap < new_cap) cap <<= 1;
    seq_t *new_queue = (seq_t *)malloc(cap * sizeof(seq_t));
    size_t remaining = q_back - q_front;
    if (remaining) memcpy(new_queue, queue + q_front, remaining * sizeof(seq_t));
    free(queue);
    queue = new_queue;
    q_front = 0;
    q_back  = remaining;
    q_cap   = cap;
}

/* Linear search for a value already generated.  Returns true
   if the value is present in seq_cache.                      */
static bool already_seen(seq_t val)
{
    for (size_t i = 0; i < seq_len; ++i)
        if (seq_cache[i] == val) return true;
    return false;
}

/* Return a(n) for the OEIS sequence A274455, n >= 1.           */
seq_t a(idx_t n)
{
    /* Lazy initialization of the tree.                            */
    if (!seq_cache) {
        ensure_seq_cache_capacity(64);
        seq_cache[0] = (seq_t)1;
        seq_len = 1;

        ensure_queue_capacity(64);
        queue[0] = (seq_t)1;
        q_back  = 1;
        q_front = 0;
    }

    /* Expand the tree until we have at least n terms.             */
    while (seq_len < (size_t)n) {
        /* Take the next node to expand.                            */
        seq_t parent = queue[q_front++];
        /* First child: parent - 1.                                 */
        seq_t child1 = parent - (seq_t)1;
        if (!already_seen(child1)) {
            ensure_seq_cache_capacity(seq_len + 1);
            seq_cache[seq_len++] = child1;
            ensure_queue_capacity(q_back + 1);
            queue[q_back++] = child1;
        }
        /* Second child: 2 * parent.                                */
        seq_t child2 = parent * (seq_t)2;
        if (!already_seen(child2)) {
            ensure_seq_cache_capacity(seq_len + 1);
            seq_cache[seq_len++] = child2;
            ensure_queue_capacity(q_back + 1);
            queue[q_back++] = child2;
        }
    }
    return seq_cache[n - 1];
}
